// Safe webcam wrapper — never crashes, gracefully degrades
import React, { forwardRef, useState } from 'react';

const SafeWebcam = forwardRef(({ className, onError, ...props }, ref) => {
  const [failed, setFailed] = useState(false);

  // Dynamically import react-webcam to catch import errors
  const [Webcam, setWebcam] = useState(null);
  const [loading, setLoading] = useState(true);

  React.useEffect(() => {
    import('react-webcam')
      .then(mod => { setWebcam(() => mod.default); setLoading(false); })
      .catch(() => { setFailed(true); setLoading(false); if (onError) onError(); });
  }, []);

  if (loading) return (
    <div className={`${className} bg-gray-800 flex items-center justify-center rounded-lg`}>
      <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white opacity-50"/>
    </div>
  );

  if (failed || !Webcam) return (
    <div className={`${className} bg-gray-800 flex items-center justify-center rounded-lg`}>
      <span className="text-gray-400 text-xs text-center px-2">Camera unavailable</span>
    </div>
  );

  return (
    <Webcam
      ref={ref}
      {...props}
      onUserMediaError={() => { setFailed(true); if (onError) onError(); }}
    />
  );
});

SafeWebcam.displayName = 'SafeWebcam';
export default SafeWebcam;
